Each frame:
```
const n = Math.max(2, ctx.inputCount); // number of array inputs
const out = [];
for (let i = 1; i <= n; i++) {
  const a = ctx.input(`array${i}`);
  if (a === null || a === undefined) continue;
  if (Array.isArray(a)) out.push(...a);
  else out.push(a);                // a single value joins as one element
}
if (out.length > 10000) { warnOnce("Array Join keeps the first 10,000 elements"); out.length = 10000; }
